insert into public.catalog_places (city, country, name, category, area, description, lat, lng, source, sheet_key, best_time, price_info)
values
 ('Séoul','Corée du Sud','Musée national de Corée','Musée','Yongsan-gu · Ichon','Le plus grand musée du pays : 5 000 ans d''histoire coréenne, de la préhistoire aux dynasties Joseon, dans un bâtiment immense bordé d''un parc et d''un étang. Prévoir au moins une demi-journée.',37.5240,126.9803,'seed','musee-national','{matin,debut-aprem}','Collections permanentes gratuites · expositions temporaires 5 000 ₩ (~3 €)'),
 ('Séoul','Corée du Sud','Musée national du palais','Musée','Jongno-gu · Gyeongbokgung','Juste à côté du palais Gyeongbokgung : trônes royaux, sceaux, horloges astronomiques et carrosses de la cour Joseon. Idéal en complément de la visite du palais.',37.5757,126.9744,'seed','musee-palais','{matin}','Gratuit'),
 ('Séoul','Corée du Sud','MMCA Séoul (art moderne)','Musée','Jongno-gu · Sogyeok-dong','Le musée national d''art moderne et contemporain, dans un ancien hôpital militaire réhabilité près de Gyeongbokgung. Beaux volumes, café agréable et scène coréenne contemporaine.',37.5785,126.9800,'seed','mmca-seoul','{debut-aprem,fin-aprem}','Adulte 4 000 ₩ (~2,5 €) · gratuit après 18 h le mercredi'),
 ('Séoul','Corée du Sud','Musée Leeum','Musée','Yongsan-gu · Hannam-dong','Fondation Samsung, trois bâtiments signés Mario Botta, Jean Nouvel et Rem Koolhaas. Art ancien coréen d''un côté, art contemporain international de l''autre. Réservation en ligne conseillée.',37.5384,127.0048,'seed','leeum','{debut-aprem,fin-aprem}','Collections permanentes gratuites · expositions temporaires ~18 000 ₩ (~11 €)'),
 ('Séoul','Corée du Sud','SeMA — Musée d''art de Séoul','Musée','Jung-gu · Jeong-dong','Ancien tribunal colonial devenu musée municipal : expositions pointues, souvent gratuites, à deux pas de Deoksugung et de la rue Jeong-dong.',37.5654,126.9750,'seed','sema','{debut-aprem}','Gratuit (certaines expositions payantes)'),
 ('Séoul','Corée du Sud','Musée d''histoire de Séoul','Musée','Jongno-gu · Gwanghwamun','Comment Séoul est passée de capitale Joseon à mégapole : maquettes, objets du quotidien, photos d''archives. Parfait pour comprendre la ville en une heure.',37.5704,126.9700,'seed','musee-histoire-seoul','{matin,debut-aprem}','Gratuit'),
 ('Séoul','Corée du Sud','Mémorial de la guerre de Corée','Musée','Yongsan-gu · Samgakji','Vaste mémorial et musée militaire : avions, chars et sous-marin à l''extérieur, récits très documentés de la guerre à l''intérieur. Émouvant et gratuit.',37.5369,126.9773,'seed','memorial-guerre','{matin,debut-aprem}','Gratuit'),
 ('Séoul','Corée du Sud','Musée national du folklore','Musée','Jongno-gu · Gyeongbokgung','Vie quotidienne traditionnelle coréenne : saisons, rites, mariages, marché reconstitué des années 70 dans la cour. Très accessible avec des enfants.',37.5817,126.9793,'seed','musee-folklore','{matin}','Gratuit'),
 ('Séoul','Corée du Sud','Musée Kimchikan','Musée','Jongno-gu · Insa-dong','Petit musée entièrement consacré au kimchi : variétés régionales, fermentation, dégustation. Une visite courte et gourmande dans Insadong.',37.5716,126.9862,'seed','kimchikan','{debut-aprem}','Adulte 5 000 ₩ (~3 €)'),
 ('Séoul','Corée du Sud','Musée Dongdaemun (DDP)','Musée','Jung-gu · Dongdaemun','Sous la coque argentée de Zaha Hadid : design, expositions, vestiges de la muraille et, le soir, l''esplanade illuminée. Le quartier vit surtout la nuit.',37.5665,127.0092,'seed','ddp','{fin-aprem,soiree}','Esplanade gratuite · expositions 8 000–15 000 ₩ (~5–9 €)'),
 ('Autour de Séoul','Corée du Sud','Nam June Paik Art Center','Musée','Yongin · Giheung','Consacré au pionnier coréen de l''art vidéo : murs d''écrans, robots télévisuels, installations sonores. 1 h de train depuis Séoul, très calme.',37.2482,127.1082,'seed','nam-june-paik','{debut-aprem}','Adulte 4 000 ₩ (~2,5 €)'),
 ('Autour de Séoul','Corée du Sud','Paju Book City & musée Mimesis','Musée','Paju · Book City','Ville-livre au nord de Séoul : maisons d''édition, librairies-entrepôts et le musée Mimesis d''Álvaro Siza, tout en béton blanc et lumière naturelle.',37.7130,126.6960,'seed','paju-mimesis','{debut-aprem,fin-aprem}','Musée ~5 000 ₩ (~3 €) · librairies gratuites'),
